/**
 * Cartesian product: [[a,b],[c,d]] -> [[a,c],[a,d],[b,c],[b,d]]
 */
export function generateCartesianProduct(optionArrays: string[][]): string[][] {
  const f = (acc: string[][], curr: string[]): string[][] => {
    if (curr.length === 0) return acc;
    if (acc.length === 0) return curr.map((x) => [x]);
    const result: string[][] = [];
    for (const a of acc) {
      for (const c of curr) {
        result.push([...a, c]);
      }
    }
    return result;
  };
  return optionArrays.reduce(f, [] as string[][]);
}
