"use client";

import { useMemo, useRef, useEffect, useState, useCallback } from "react";
import type { ClassificationGroup, VariationRow, FirstColSpanInfo } from "../types";
import { generateCartesianProduct } from "../utils/generateCartesianProduct";
import { validateSalesInfo } from "../utils/validateSalesInfo";

export function useSalesInfo() {
  const [classifications, setClassifications] = useState<ClassificationGroup[]>(
    [],
  );
  const [variationValues, setVariationValues] = useState<
    Record<string, { price: string; stock: string }>
  >({});
  const [optionDrafts, setOptionDrafts] = useState<Record<string, string>>({});
  const [salesInfoErrors, setSalesInfoErrors] = useState<string[]>([]);
  const [firstOptionImages, setFirstOptionImages] = useState<
    Record<string, { file: File; previewUrl: string }>
  >({});
  const firstOptionImagesRef = useRef(firstOptionImages);
  firstOptionImagesRef.current = firstOptionImages;

  const classificationsWithOptions = useMemo(
    () => classifications.filter((c) => c.options.length > 0),
    [classifications],
  );

  const cartesianProduct = useMemo(
    () =>
      generateCartesianProduct(
        classificationsWithOptions.map((c) => c.options),
      ),
    [classificationsWithOptions],
  );

  const variationRows: VariationRow[] = useMemo(() => {
    if (cartesianProduct.length === 0) return [null];
    return cartesianProduct.map((combo) => ({
      key: combo.join("|"),
      labels: combo,
    }));
  }, [cartesianProduct]);

  const firstColSpanInfo: FirstColSpanInfo = useMemo(() => {
    if (classificationsWithOptions.length === 0 || variationRows.length === 0)
      return null;
    const firstCls = classificationsWithOptions[0];
    const restSize =
      classificationsWithOptions
        .slice(1)
        .reduce((acc, c) => acc * c.options.length, 1) || 1;
    return {
      options: firstCls.options,
      rowSpan: restSize,
    };
  }, [classificationsWithOptions, variationRows]);

  useEffect(() => {
    return () => {
      Object.values(firstOptionImagesRef.current).forEach(({ previewUrl }) =>
        URL.revokeObjectURL(previewUrl),
      );
    };
  }, []);

  const addClassification = useCallback(() => {
    if (classifications.length >= 2) return;
    setClassifications((prev) => [
      ...prev,
      { id: `cls-${Date.now()}`, name: "", options: [] },
    ]);
  }, [classifications.length]);

  const removeClassification = useCallback((id: string) => {
    setClassifications((prev) => prev.filter((c) => c.id !== id));
    setOptionDrafts((prev) => {
      const next = { ...prev };
      delete next[id];
      return next;
    });
  }, []);

  const updateClassificationName = useCallback((id: string, name: string) => {
    setClassifications((prev) =>
      prev.map((c) => (c.id === id ? { ...c, name } : c)),
    );
  }, []);

  const addOption = useCallback(
    (clsId: string, option: string) => {
      const trimmed = option.trim();
      if (!trimmed) return;
      const cls = classifications.find((c) => c.id === clsId);
      if (!cls || cls.options.includes(trimmed)) return;
      setClassifications((prev) =>
        prev.map((c) =>
          c.id === clsId
            ? { ...c, options: [...c.options, trimmed] }
            : c,
        ),
      );
      setOptionDrafts((prev) => ({ ...prev, [clsId]: "" }));
    },
    [classifications],
  );

  const removeOption = useCallback((clsId: string, option: string) => {
    setClassifications((prev) =>
      prev.map((c) =>
        c.id === clsId
          ? { ...c, options: c.options.filter((o) => o !== option) }
          : c,
      ),
    );
  }, []);

  const updateVariationValue = useCallback(
    (key: string, field: "price" | "stock", value: string) => {
      setVariationValues((prev) => {
        const cur = prev[key] ?? { price: "", stock: "" };
        return { ...prev, [key]: { ...cur, [field]: value } };
      });
    },
    [],
  );

  const validate = useCallback((): boolean => {
    const { valid, errors } = validateSalesInfo(
      classifications,
      variationRows,
      variationValues,
    );
    setSalesInfoErrors(errors);
    return valid;
  }, [classifications, variationRows, variationValues]);

  const handleFirstOptionImageUpload = useCallback(
    (option: string, e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0];
      if (!file || !file.type.startsWith("image/")) return;
      setFirstOptionImages((prev) => {
        const old = prev[option];
        if (old?.previewUrl) URL.revokeObjectURL(old.previewUrl);
        return {
          ...prev,
          [option]: { file, previewUrl: URL.createObjectURL(file) },
        };
      });
      e.target.value = "";
    },
    [],
  );

  const removeFirstOptionImage = useCallback((option: string) => {
    setFirstOptionImages((prev) => {
      const old = prev[option];
      if (old?.previewUrl) URL.revokeObjectURL(old.previewUrl);
      const next = { ...prev };
      delete next[option];
      return next;
    });
  }, []);

  const resetAfterSubmit = useCallback(() => {
    setVariationValues({});
    setClassifications([]);
    setFirstOptionImages({});
  }, []);

  return {
    classifications,
    setClassifications,
    variationValues,
    setVariationValues,
    optionDrafts,
    setOptionDrafts,
    salesInfoErrors,
    classificationsWithOptions,
    variationRows,
    firstColSpanInfo,
    firstOptionImages,
    addClassification,
    removeClassification,
    updateClassificationName,
    addOption,
    removeOption,
    updateVariationValue,
    validate,
    handleFirstOptionImageUpload,
    removeFirstOptionImage,
    resetAfterSubmit,
  };
}
